import{_ as e,o,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Lei de Garantia Educacional","description":"","frontmatter":{},"headers":[],"relativePath":"pt/43-教育保障法.md","filePath":"pt/43-教育保障法.md","lastUpdated":1789183869000}'),d={name:"pt/43-教育保障法.md"};function s(r,a,c,n,u,l){return o(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="lei-de-garantia-educacional" tabindex="-1">Lei de Garantia Educacional <a class="header-anchor" href="#lei-de-garantia-educacional" aria-label="Permalink to &quot;Lei de Garantia Educacional&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>43</td></tr><tr><td>Módulo</td><td>Sistema Jurídico e Estrutura de Governança</td></tr><tr><td>Palavras-chave principais</td><td>Direito à Educação, Educação Simbiótica, Transmissão de Cultivo, Aprendizagem ao Longo da Vida, Equidade Educacional</td></tr></tbody></table><h2 id="i-objetivo-legislativo-e-principios-fundamentais" tabindex="-1">I. Objetivo Legislativo e Princípios Fundamentais <a class="header-anchor" href="#i-objetivo-legislativo-e-principios-fundamentais" aria-label="Permalink to &quot;I. Objetivo Legislativo e Princípios Fundamentais&quot;">​</a></h2><p>A 《Lei de Garantia Educacional》 é uma das cinco leis complementares da civilização simbiótica de âncoras, visando garantir o direito à educação de todos os seres dentro de Hengyuanzhou, estabelecer um sistema educacional com o conceito central de &quot;evolução simbiótica&quot;, e fornecer suporte de conhecimento e talentos para o progresso comum de todas as raças.</p><p>Esta lei estabelece os seguintes princípios fundamentais:</p><table tabindex="0"><thead><tr><th>Princípio</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Princípio da Equidade Educacional</td><td>Todos os seres, independentemente de raça, nível de cultivo, origem, desfrutam de iguais oportunidades educacionais</td></tr><tr><td>Princípio do Ensino de Acordo com a Aptidão</td><td>Respeitar as diferenças de talento e a escolha do caminho de evolução de cada ser, fornecendo planos educacionais personalizados</td></tr><tr><td>Princípio da Unidade de Conhecimento e Ação</td><td>Combinar conhecimento teórico e cultivo prático, opor-se à educação de conversas vazias desconectadas da realidade</td></tr><tr><td>Princípio da Abertura e Compartilhamento</td><td>Recursos educacionais abertos a toda a sociedade, os métodos básicos dos trezentos sistemas de cultivo de origem são ensinados gratuitamente</td></tr><tr><td>Princípio da Aprendizagem ao Longo da Vida</td><td>A educação permeia todo o processo da vida, apoiando a aprendizagem contínua e a melhoria de habilidades em todas as fases</td></tr><tr><td>Princípio da Diversidade Cultural</td><td>Respeitar as tradições culturais de cada raça, incentivar o intercâmbio e o aprendizado mútuo multicultural</td></tr></tbody></table><h2 id="ii-garantia-juridica-do-direito-a-educacao" tabindex="-1">II. Garantia Jurídica do Direito à Educação <a class="header-anchor" href="#ii-garantia-juridica-do-direito-a-educacao" aria-label="Permalink to &quot;II. Garantia Jurídica do Direito à Educação&quot;">​</a></h2><p>Esta lei estabelece claramente que o direito à educação é um direito fundamental concedido a cada ser pela Constituição Simbiótica, e o Estado e a civilização têm a obrigação de garantir a realização deste direito:</p><ol><li><strong>Educação Básica Gratuita</strong>: Todos os seres têm o direito de receber educação básica gratuita, incluindo conhecimentos gerais, métodos básicos de cultivo, conceitos da civilização simbiótica, etc., com duração de seis a doze anos, ajustada de acordo com o ciclo de desenvolvimento da raça.</li><li><strong>Introdução Gratuita ao Cultivo</strong>: Os métodos básicos dos trezentos sistemas de cultivo de origem do universo estão abertos gratuitamente a todos os seres, nenhuma organização ou indivíduo pode apropriar-se dos métodos básicos de cultivo como propriedade privada e ensiná-los mediante pagamento.</li><li><strong>Igualdade de Oportunidades de Progressão Escolar</strong>: Instituições educacionais de todos os níveis e tipos não podem estabelecer condições discriminatórias como raça, nível de cultivo, origem, etc. na admissão, e os critérios de admissão devem ser abertos e transparentes.</li><li><strong>Garantia de Educação Especial</strong>: Fornecer recursos educacionais especiais adaptados e suporte de educação a distância para grupos como seres com deficiência, seres de outras raças, seres de planos remotos, etc.</li><li><strong>Sistema de Assistência Educacional</strong>: Fornecer bolsas de estudo, prêmios de mérito e empréstimos sem juros para estudantes com dificuldades financeiras, garantindo que não percam a oportunidade educacional por razões econômicas.</li></ol><h2 id="iii-estrutura-do-sistema-educacional" tabindex="-1">III. Estrutura do Sistema Educacional <a class="header-anchor" href="#iii-estrutura-do-sistema-educacional" aria-label="Permalink to &quot;III. Estrutura do Sistema Educacional&quot;">​</a></h2><p>O sistema educacional da civilização simbiótica de âncoras é dividido em quatro níveis, organicamente conectados entre si:</p><table tabindex="0"><thead><tr><th>Nível</th><th>Nome</th><th>Objetivo</th><th>Duração</th></tr></thead><tbody><tr><td>Primeiro nível</td><td>Educação Inicial</td><td>Cultivar habilidades cognitivas básicas e consciência simbiótica, ensinar métodos básicos de cultivo</td><td>3-6 anos</td></tr><tr><td>Segundo nível</td><td>Educação Básica</td><td>Aprendizado sistemático de conhecimentos gerais e teoria de cultivo, descobrir a direção do talento individual</td><td>6-9 anos</td></tr><tr><td>Terceiro nível</td><td>Educação Profissional</td><td>Aprendizado aprofundado e prática no sistema de cultivo ou área profissional selecionada</td><td>3-10 anos</td></tr><tr><td>Quarto nível</td><td>Estudo Avançado</td><td>Exploração de ponta e estudo inovador voltado para cultivadores avançados e pesquisadores</td><td>Ilimitado</td></tr></tbody></table><p>Além disso, foi estabelecido o &quot;Sistema de Rede de Mentores&quot;: cultivadores que atingem um certo nível de cultivo têm a obrigação de orientar cultivadores iniciantes dentro de sua capacidade, e a contribuição da orientação é contabilizada na quantidade de contribuição do mecanismo de contrato de produção conjunta, desfrutando da distribuição de recursos correspondente.</p><h2 id="iv-instituicoes-educacionais-e-professores" tabindex="-1">IV. Instituições Educacionais e Professores <a class="header-anchor" href="#iv-instituicoes-educacionais-e-professores" aria-label="Permalink to &quot;IV. Instituições Educacionais e Professores&quot;">​</a></h2><ul><li><strong>Instituições Educacionais Públicas</strong>: Estabelecidas pelo Estado ou pela comunidade da civilização, responsáveis pela educação básica gratuita e serviços educacionais públicos, com financiamento garantido pelo acúmulo público.</li><li><strong>Instituições Educacionais Privadas</strong>: Estabelecidas por forças sociais de acordo com a lei, podem cobrar taxas razoáveis, mas devem aceitar a supervisão do departamento competente de educação, e não podem fazer propaganda falsa nem cobrar taxas predatórias.</li><li><strong>Seitas de Cultivo</strong>: Organizações tradicionais de cultivo podem, após registro, atuar como instituições educacionais profissionais, devem cumprir as disposições da lei educacional, e não podem monopolizar e fechar os recursos de cultivo.</li><li><strong>Direitos e Deveres dos Professores</strong>: Os professores desfrutam de direitos como liberdade acadêmica, remuneração razoável, formação profissional, etc., e ao mesmo tempo têm o dever de ensinar e educar, servir de modelo, manter a privacidade dos alunos, etc.</li></ul><h2 id="v-conteudo-educacional-e-padroes-curriculares" tabindex="-1">V. Conteúdo Educacional e Padrões Curriculares <a class="header-anchor" href="#v-conteudo-educacional-e-padroes-curriculares" aria-label="Permalink to &quot;V. Conteúdo Educacional e Padrões Curriculares&quot;">​</a></h2><p>O conteúdo educacional deve atender aos seguintes requisitos:</p><ol><li>Incluir o conceito central da civilização simbiótica e a educação anti-predatória, cultivando a consciência simbiótica dos alunos.</li><li>Incluir a teoria básica e os métodos introdutórios dos trezentos sistemas de cultivo de origem.</li><li>Incluir conhecimentos científicos gerais como leis do universo, conhecimento de planos, ciências da vida, etc.</li><li>Incluir a história e a cultura de todas as raças, promovendo o entendimento e o respeito mútuos entre as raças.</li><li>Incluir环节 de cultivo prático e serviço social, cultivando a capacidade de unir conhecimento e ação.</li><li>Proibir a disseminação de conceitos de cultivo predatório e ideias discriminatórias.</li></ol><h2 id="vi-responsabilidade-juridica" tabindex="-1">VI. Responsabilidade Jurídica <a class="header-anchor" href="#vi-responsabilidade-juridica" aria-label="Permalink to &quot;VI. Responsabilidade Jurídica&quot;">​</a></h2><p>Atividades que violam as disposições desta lei assumem as seguintes responsabilidades de acordo com a gravidade da infração:</p><ul><li>Recusar ou dificultar que seres em idade escolar recebam educação obrigatória, ordenar a correção e impor punição.</li><li>Instituições educacionais que cobram taxas ilegais ou fazem propaganda falsa, ordenar o reembolso das taxas e impor multa, em casos graves revogar a licença de funcionamento.</li><li>Professores que aplicam castigos físicos ou discriminam alunos, aplicar punição, em casos graves revogar a qualificação docente e追究 responsabilidade jurídica.</li><li>Apropriar-se de recursos públicos de cultivo como propriedade privada, monopolizar e cobrar taxas, confiscar os ganhos ilegais e impor multa.</li></ul><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A 《Lei de Garantia Educacional》 é a prática educacional do conceito de &quot;todos têm um caminho&quot; da civilização simbiótica de âncoras. Ao garantir o direito à educação, construir um sistema educacional hierárquico e abrir os recursos de cultivo, ela garante que cada ser possa obter um caminho de evolução adequado a si mesmo, fornecendo continuamente conhecimento e talentos para o progresso comum de todas as raças.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Princípios Gerais da Constituição Simbiótica)</li><li>37-共生教育体系 (Sistema Educacional Simbiótico)</li><li>10-三百套本源修炼体系总览 (Visão Geral dos Trezentos Sistemas de Cultivo de Origem)</li><li>08-人人有路保障体系 (Sistema de Garantia de que Todos Têm um Caminho)</li></ul>',25)])])}const v=e(d,[["render",s]]);export{p as __pageData,v as default};
